 for(var i=0;i luckElements.length;i++){
   luckElements[i].value = elm.value;
 }
}

function doIniPage(){
	document.getElementById('sggzyplatnamespan').innerText =document.getElementById('sggzyplatname').value;
	document.getElementById('sggzyplatwebsitespan').innerText =document.getElementById('sggzyplatwebsite').value;

	var zbfstext = document.getElementById("zbfs").value;
	if(zbfstext=="公开招标"){
		document.getElementById("changeline1").innerText="招标公告";
		document.getElementById("changeline2").innerText="招标公告";
		document.getElementById("changeline3").style.display="none";
		document.getElementById("changeline4").innerText="现对该项目的施工进行公开招标。";
		document.getElementById("changeline6").innerText="采取无记名方式";	
		document.getElementById("invitediv").style.display="none";
		document.getElementById("opendiv").style.display="inline";
		document.getElementById("t_inviteman_20171223153253569").setAttribute("showOrNot","0"); 
		document.getElementById("i_invitetime_20171223153253588").setAttribute("showOrNot","0"); 
		document.getElementById("t_platformname_20221223153253588").setAttribute("showOrNot","0"); 
		
	}
	else if(zbfstext=="邀请招标"){
		document.getElementById("changeline1").innerText="投标邀请书";
		document.getElementById("changeline2").innerText="投标邀请书";
		document.getElementById("changeline3").style.display="inline";
		document.getElementById("changeline4").innerText="现邀请你单位参加本招标项目施工投标。";
		document.getElementById("changeline6").innerText="";
		document.getElementById("invitediv").style.display="inline";
		document.getElementById("opendiv").style.display="none";	
		document.getElementById("t_inviteman_20171223153253569").setAttribute("showOrNot","1"); 
		document.getElementById("i_invitetime_20171223153253588").setAttribute("showOrNot","1"); 
		document.getElementById("t_platformname_20221223153253588").setAttribute("showOrNot","1"); 
	}
	//评标办法
	var bidevamethods=document.getElementById("bidevamethods").value;
	if(bidevamethods=="2262" || bidevamethods=="2247") 
		document.getElementById("bidevamethodstext").innerText="简易评标法";
	if(bidevamethods=="2280" || bidevamethods=="2250"|| bidevamethods=="2281"|| bidevamethods=="2251" || bidevamethods=="2274" || bidevamethods=="2221"|| bidevamethods=="2275"|| bidevamethods=="2242") 	
		document.getElementById("bidevamethodstext").innerText="经评审的最低投标价中标法";	
	if(bidevamethods=="2297" || bidevamethods=="2252"|| bidevamethods=="2296"|| bidevamethods=="2261" || bidevamethods=="2277" || bidevamethods=="2244"|| bidevamethods=="2279"|| bidevamethods=="2245") 	
		document.getElementById("bidevamethodstext").innerText="综合评估法";	
	
	//泉州增加输入框
	var qzdemandvartext=document.getElementById("qzdemandvar").value;
	if(qzdemandvartext=="1"){	 //泉州
		document.getElementById("qzdemand1").style.display="inline";
		document.getElementById("qzdemand2").style.display="inline";
		document.getElementById("qzdemand3").style.display="inline";
	}
	else {	 //非泉州
		document.getElementById("qzdemand1").style.display="none";
		document.getElementById("qzdemand2").style.display="none";
		document.getElementById("qzdemand3").style.display="none";
	}
	
}

